using System;
using System.IO;
using System.Linq;
using SplifyWin;
class WindowsCoreCompatibilityChecks {
 static int Main(string[] args){try{var core=new NetworkCore(new StateStore(Path.GetFullPath(args[0])));if(!CoreProcessHost.SupportsControl(core.Executable))throw new Exception("Bundled private core unsupported");Console.WriteLine("PASS bundled GUI core supports private STOP");if(CoreProcessHost.SupportsControl(args[1]))throw new Exception("Original core incorrectly accepted");Console.WriteLine("PASS original upstream core cannot replace private lifecycle contract");bool rejected=false;try{CoreProcessHost.StartInfo(args[1],"fixture.json");}catch(InvalidOperationException){rejected=true;}if(!rejected)throw new Exception("Unsupported core would be launched");Console.WriteLine("PASS incompatible core rejected before launch");var all=core.Engines.Packages.ToList();var json=new System.Web.Script.Serialization.JavaScriptSerializer();var old=json.Deserialize<EngineCatalog>(json.Serialize(new EngineCatalog{Version=1,Engines=all.Where(p=>!new[]{"csqtt20","csqtt215","csqtt25"}.Contains(p.Id)).ToList()}));old.Engines.Single(p=>p.Id=="csqtt").Version="legacy-existing-package";var unrelated=old.Engines.Single(p=>p.Id=="openflux");var merged=OptionalEngines.MergeEmbeddedRequirements(old,new EngineCatalog{Version=1,Engines=all});if(merged.Engines.Single(p=>p.Id=="csqtt").Version=="legacy-existing-package"||merged.Engines.Count!=7||merged.Engines.Single(p=>p.Id=="openflux")!=unrelated)throw new Exception("Legacy catalogue hides new CSQTT requirements");Console.WriteLine("PASS existing catalogue upgrades required CSQTT pin and preserves unrelated packages");Console.WriteLine("RESULT 4 checks PASS; no core or VPN started");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
